import os, re

hex_re = re.compile(r"#[0-9a-fA-F]{3,8}\b")
matches = []

for root, dirs, files in os.walk("."):
    if any(p in root for p in [".git", "node_modules", ".pio", "build", ".agents/skills/framework-portal-design"]):
        continue
    for f in files:
        if f.endswith((".css", ".js", ".html", ".cpp", ".h")):
            path = os.path.join(root, f)
            try:
                with open(path, "r", errors="ignore") as fp:
                    for i, line in enumerate(fp, 1):
                        found = hex_re.findall(line)
                        if found:
                            matches.append((path, i, line.strip(), found))
            except Exception as e:
                pass

print(f"Total occurrences: {len(matches)}")
